import numpy as np
import time
from fealpy.mesh import boxmesh2d
from fealpy.functionspace import LinearLagrangeFiniteElementSpace
from fealpy.pde.linear_elasticity_model import LinearElasticityModel
from fealpy.tools.show import show_mesh_2d
from fealpy.solver import LinearElasticityLFEMFastSolver

class BoxDomain2D:
    def __init__(self, box=[0, 1, 0, 1], nx=10, ny=10, E=1e5, nu=0.3, body_force=None):
        self.box = box
        self.nx = nx
        self.ny = ny
        self.E = E
        self.nu = nu
        self.mesh = self.init_mesh()
        self.lam = E * nu / ((1 + nu) * (1 - 2 * nu))
        self.mu = E / (2 * (1 + nu))
        self.body_force = body_force if body_force is not None else self.source

    def init_mesh(self):
        mesh = boxmesh2d(self.box, nx=self.nx, ny=self.ny)
        return mesh

    def displacement(self, p):
        # Zero displacement
        return np.zeros((2, p.shape[1]))

    def strain(self, grad_u):
        # grad_u: shape (2, 2, N)
        eps = 0.5 * (grad_u + np.transpose(grad_u, (1, 0, 2)))
        return eps

    def stress(self, grad_u):
        # grad_u: shape (2, 2, N)
        eps = self.strain(grad_u)
        trace_eps = np.trace(eps, axis1=0, axis2=1)
        sigma = self.lam * trace_eps * np.eye(2)[:, :, None] + 2 * self.mu * eps
        return sigma

    def source(self, p):
        # Zero body force
        return np.zeros((2, p.shape[1]))

    def dirichlet_bc(self, p):
        # Zero displacement on Dirichlet boundary
        return np.zeros((2, p.shape[1]))

    def neumann_bc(self, p, n):
        # Zero traction on Neumann boundary
        return np.zeros((2, p.shape[1]))

    def is_dirichlet_boundary(self, p):
        x, y = p
        tol = 1e-12
        return (np.abs(x - self.box[0]) < tol) | (np.abs(x - self.box[1]) < tol)

    def is_neumann_boundary(self, p):
        x, y = p
        tol = 1e-12
        return (np.abs(y - self.box[2]) < tol) | (np.abs(y - self.box[3]) < tol)

    def is_fracture_boundary(self, p):
        # No fracture in this example
        return np.zeros(p.shape[1], dtype=bool)

class IterationCounter:
    def __init__(self):
        self.count = 0

    def __call__(self, rk=None):
        self.count += 1

class FastElasticitySolver:
    def __init__(self, A, b):
        self.A = A
        self.b = b

    def precondition(self):
        # Jacobi preconditioner
        M_inv = 1.0 / self.A.diagonal()
        return M_inv

    def solve(self, tol=1e-8, maxiter=1000, callback=None):
        from scipy.sparse.linalg import cg
        M_inv = self.precondition()
        def precond(x):
            return M_inv * x
        x, info = cg(self.A, self.b, tol=tol, maxiter=maxiter, callback=callback, M=None)
        return x

if __name__ == '__main__':
    # Initialize domain and mesh
    domain = BoxDomain2D(box=[0, 1, 0, 1], nx=32, ny=32, E=1e5, nu=0.3)
    mesh = domain.mesh

    # Define finite element space
    space = LinearLagrangeFiniteElementSpace(mesh, dim=2)

    # Dirichlet boundary condition
    def is_dirichlet(p):
        return domain.is_dirichlet_boundary(p)

    def dirichlet_value(p):
        return domain.dirichlet_bc(p)

    # Neumann boundary condition
    def is_neumann(p):
        return domain.is_neumann_boundary(p)

    def neumann_value(p, n):
        return domain.neumann_bc(p, n)

    # Solution function
    uh = space.function(dim=2)

    # Assemble stiffness matrix and right-hand side
    model = LinearElasticityModel(lam=domain.lam, mu=domain.mu, f=domain.body_force)
    A = model.linear_elasticity_matrix(space)
    F = model.source_vector(space)

    # Apply Neumann BC
    F += model.neumann_vector(space, is_neumann, neumann_value)

    # Apply Dirichlet BC
    is_dof_dirichlet = space.is_boundary_dof(is_dirichlet)
    dirichlet_dof = np.where(is_dof_dirichlet)[0]
    dirichlet_val = space.interpolation(dirichlet_value)
    from scipy.sparse import lil_matrix
    A = A.tolil()
    for dof in dirichlet_dof:
        A[dof, :] = 0
        A[dof, dof] = 1
        F[dof] = dirichlet_val[dof]
    A = A.tocsr()

    print("Matrix shape:", A.shape)

    # Solve system
    solver = FastElasticitySolver(A, F)
    t0 = time.time()
    uh[:] = solver.solve()
    t1 = time.time()
    print("Solve time: {:.4f} seconds".format(t1 - t0))

    # Plot mesh
    show_mesh_2d(mesh)
